{
  "name": "fast-uri",
  "description": "Dependency-free RFC 3986 URI toolbox",
  "version": "3.1.2",
  "main": "index.js",
  "type": "commonjs",
  "types": "types/index.d.ts",
  "license": "BSD-3-Clause",
  "author": "Vincent Le Goff <vince.legoff@gmail.com> (https://github.com/zekth)",
  "contributors": [
    {
      "name": "Matteo Collina",
      "email": "hello@matteocollina.com"
    },
    {
      "name": "Gürgün Dayıoğlu",
      "email": "hey@gurgun.day",
      "url": "https://heyhey.to/G"
    },
    {
      "name": "Aras Abbasi",
      "email": "aras.abbasi@gmail.com"
    },
    {
      "name": "Frazer Smith",
      "email": "frazer.dev@icloud.com",
      "url": "https://github.com/fdawgs"
    }
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fastify/fast-uri.git"
  },
  "bugs": {
    "url": "https://github.com/fastify/fast-uri/issues"
  },
  "homepage": "https://github.com/fastify/fast-uri",
  "funding": [
    {
      "type": "github",
      "url": "https://github.com/sponsors/fastify"
    },
    {
      "type": "opencollective",
      "url": "https://opencollective.com/fastify"
    }
  ],
  "scripts": {
    "lint": "eslint",
    "lint:fix": "eslint --fix",
    "test": "npm run test:unit && npm run test:typescript",
    "test:browser:chromium": "playwright-test ./test/* --runner tape --browser=chromium",
    "test:browser:firefox": "playwright-test ./test/* --runner tape --browser=firefox",
    "test:browser:webkit": "playwright-test ./test/* --runner tape --browser=webkit",
    "test:browser": "npm run test:browser:chromium && npm run test:browser:firefox && npm run test:browser:webkit",
    "test:unit": "tape test/**/*.js",
    "test:unit:dev": "npm run test:unit -- --coverage-report=html",
    "test:typescript": "tsd"
  },
  "devDependencies": {
    "ajv": "^8.16.0",
    "eslint": "^9.17.0",
    "neostandard": "^0.13.0",
    "playwright-test": "^14.1.12",
    "tape": "^5.8.1",
    "tsd": "^0.33.0"
  }
}

{
  "name": "json-schema-traverse",
  "version": "1.0.0",
  "description": "Traverse JSON Schema passing each schema object to callback",
  "main": "index.js",
  "types": "index.d.ts",
  "scripts": {
    "eslint": "eslint index.js spec",
    "test-spec": "mocha spec -R spec",
    "test": "npm run eslint && nyc npm run test-spec"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/epoberezkin/json-schema-traverse.git"
  },
  "keywords": [
    "JSON-Schema",
    "traverse",
    "iterate"
  ],
  "author": "Evgeny Poberezkin",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/epoberezkin/json-schema-traverse/issues"
  },
  "homepage": "https://github.com/epoberezkin/json-schema-traverse#readme",
  "devDependencies": {
    "eslint": "^7.3.1",
    "mocha": "^8.0.1",
    "nyc": "^15.0.0",
    "pre-commit": "^1.2.2"
  },
  "nyc": {
    "exclude": [
      "**/spec/**",
      "node_modules"
    ],
    "reporter": [
      "lcov",
      "text-summary"
    ]
  }
}

{
  "name": "zod",
  "version": "4.6.7",
  "type": "module",
  "license": "MIT",
  "author": "Colin McDonnell <zod@colinhacks.com>",
  "description": "TypeScript-first schema declaration and validation library with static type inference",
  "homepage": "https://zod.dev",
  "llms": "https://zod.dev/llms.txt",
  "llmsFull": "https://zod.dev/llms-full.txt",
  "mcpServer": "https://mcp.inkeep.com/zod/mcp",
  "funding": "https://github.com/sponsors/colinhacks",
  "sideEffects": [
    "./compile.js",
    "./compile.cjs",
    "./src/compile.ts"
  ],
  "files": [
    "src",
    "**/*.js",
    "**/*.mjs",
    "**/*.cjs",
    "**/*.d.ts",
    "**/*.d.mts",
    "**/*.d.cts",
    "**/package.json"
  ],
  "keywords": [
    "typescript",
    "schema",
    "validation",
    "type",
    "inference"
  ],
  "main": "./index.cjs",
  "types": "./index.d.cts",
  "module": "./index.js",
  "zshy": {
    "exports": {
      "./package.json": "./package.json",
      ".": "./src/index.ts",
      "./mini": "./src/mini/index.ts",
      "./compile": "./src/compile.ts",
      "./locales": "./src/locales/index.ts",
      "./v3": "./src/v3/index.ts",
      "./v4": "./src/v4/index.ts",
      "./v4-mini": "./src/v4-mini/index.ts",
      "./v4/mini": "./src/v4/mini/index.ts",
      "./v4/core": "./src/v4/core/index.ts",
      "./v4/locales": "./src/v4/locales/index.ts",
      "./v4/locales/*": "./src/v4/locales/*"
    },
    "conditions": {
      "@zod/source": "src"
    },
    "sealCjsExports": true
  },
  "exports": {
    "./package.json": "./package.json",
    ".": {
      "@zod/source": "./src/index.ts",
      "types": "./index.d.cts",
      "import": "./index.js",
      "require": "./index.cjs"
    },
    "./mini": {
      "@zod/source": "./src/mini/index.ts",
      "types": "./mini/index.d.cts",
      "import": "./mini/index.js",
      "require": "./mini/index.cjs"
    },
    "./compile": {
      "@zod/source": "./src/compile.ts",
      "types": "./compile.d.cts",
      "import": "./compile.js",
      "require": "./compile.cjs"
    },
    "./locales": {
      "@zod/source": "./src/locales/index.ts",
      "types": "./locales/index.d.cts",
      "import": "./locales/index.js",
      "require": "./locales/index.cjs"
    },
    "./v3": {
      "@zod/source": "./src/v3/index.ts",
      "types": "./v3/index.d.cts",
      "import": "./v3/index.js",
      "require": "./v3/index.cjs"
    },
    "./v4": {
      "@zod/source": "./src/v4/index.ts",
      "types": "./v4/index.d.cts",
      "import": "./v4/index.js",
      "require": "./v4/index.cjs"
    },
    "./v4-mini": {
      "@zod/source": "./src/v4-mini/index.ts",
      "types": "./v4-mini/index.d.cts",
      "import": "./v4-mini/index.js",
      "require": "./v4-mini/index.cjs"
    },
    "./v4/mini": {
      "@zod/source": "./src/v4/mini/index.ts",
      "types": "./v4/mini/index.d.cts",
      "import": "./v4/mini/index.js",
      "require": "./v4/mini/index.cjs"
    },
    "./v4/core": {
      "@zod/source": "./src/v4/core/index.ts",
      "types": "./v4/core/index.d.cts",
      "import": "./v4/core/index.js",
      "require": "./v4/core/index.cjs"
    },
    "./v4/locales": {
      "@zod/source": "./src/v4/locales/index.ts",
      "types": "./v4/locales/index.d.cts",
      "import": "./v4/locales/index.js",
      "require": "./v4/locales/index.cjs"
    },
    "./v4/locales/*": {
      "@zod/source": "./src/v4/locales/*",
      "types": "./v4/locales/*",
      "import": "./v4/locales/*",
      "require": "./v4/locales/*"
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/colinhacks/zod.git"
  },
  "bugs": {
    "url": "https://github.com/colinhacks/zod/issues"
  },
  "support": {
    "backing": {
      "npm-funding": true
    }
  },
  "scripts": {
    "clean": "git clean -xdf . -e node_modules",
    "build": "nub exec --node zshy --project tsconfig.build.json",
    "postbuild": "nub ../../scripts/write-stub-package-jsons.ts && nub exec --node biome check --write .",
    "test:watch": "nub exec --node vitest",
    "test": "nub exec --node vitest run",
    "prepublishOnly": "nub ../../scripts/check-versions.ts"
  }
}
